function t.RemoveTrinket(p1) --[[ RemoveTrinket | Line: 110 | Upvalues: t2 (copy), StatModifierManager (copy) ]]
	local Trinkets = p1:WaitForChild("Trinkets")
	local Trinket1 = Trinkets:FindFirstChild("Trinket1")
	local Trinket2 = Trinkets:FindFirstChild("Trinket2")

	if not (Trinket1 and Trinket2) then
		return "CantRemove"
	end

	if t2[p1] and t2[p1].currentModifiers then
		local Stats = p1:FindFirstChild("Stats")
		local v1 = t2[p1]

