			if Stats then
				local CurrentStamina = Stats:FindFirstChild("CurrentStamina")

				if CurrentStamina then
					CurrentStamina.Value = CurrentStamina.Value / 1.12
				end
			end
		elseif v1.statType == "SkillCheck" then
			StatModifierManager.RemoveModifier(p1, "BoundarySize", v1.currentModifiers.boundaryModifierId)

			if v1.currentModifiers.skillCheckModId then
				StatModifierManager.RemoveAdditiveSkillCheckChance(p1, v1.currentModifiers.skillCheckModId)
			end
		elseif v1.statType == "DecodeSpeed" then
			StatModifierManager.RemoveModifier(p1, "DecodeSpeedModifier", v1.currentModifiers.decodeModifierId)
		elseif v1.statType == "Stealth" then
			StatModifierManager.RemoveModifier(p1, "StealthModifier", v1.currentModifiers.stealthModifierId)
		end

		t2[p1] = nil
